import spinal.core._
import spinal.lib._

case class FPGATop() extends Component {
  val io = new Bundle {
    val clk = in Bool
    val rst = in Bool
    val input_data = slave Stream Bits(32 bits)
    val output_data = master Stream Bits(32 bits)
    val tensor_ready = out Bool
    val ssm_state = out Bits(18432 bits)
    val kan_spline = out Vec(Bits(16 bits), 7)
    val tgn_update = out Bool
    val quantum_phase = in Bits(64 bits)
    val led = out Bits(8 bits)
  }

  val clockDomain = ClockDomain(
    clock = io.clk,
    reset = io.rst,
    config = ClockDomainConfig(resetKind = SYNC)
  )

  val area = new ClockingArea(clockDomain) {
    val neuromorphicCore = NeuromorphicCore()
    neuromorphicCore.io.input << io.input_data
    io.output_data << neuromorphicCore.io.output
    io.tensor_ready := neuromorphicCore.io.ready

    val ssm = SSMModule()
    io.ssm_state := ssm.io.state

    val kan = KANLayer(7)
    io.kan_spline := kan.io.basis

    val tgn = TGNUpdateUnit()
    io.tgn_update := tgn.io.updated

    val phaseRot = PhaseRotator(88)
    phaseRot.io.phi := io.quantum_phase
    phaseRot.io.control := True

    val trigNeu = Reg(Bool()) init(False)
    val stepSsm = Reg(Bool()) init(False)
    val evalKan = Reg(Bool()) init(False)
    val updateTgn = Reg(Bool()) init(False)
    val rotatePhase = Reg(Bool()) init(False)

    neuromorphicCore.io.trigger := trigNeu
    ssm.io.step := stepSsm
    kan.io.eval := evalKan
    tgn.io.update := updateTgn
    phaseRot.io.rotate := rotatePhase

    io.led := B(0, 8 bits)
    io.led(0) := neuromorphicCore.io.ready
    io.led(1) := ssm.io.stable
    io.led(2) := kan.io.converged
    io.led(3) := tgn.io.updated
    io.led(4) := phaseRot.io.entangled

    val fsm = new spinal.lib.fsm.StateMachine {
      val idle = new State with Entry {
        whenIsActive {
          trigNeu := False
          stepSsm := False
          evalKan := False
          updateTgn := False
          rotatePhase := False
          when(io.input_data.valid) {
            goto(compute)
          }
        }
      }
      val compute = new State {
        whenIsActive {
          trigNeu := True
          stepSsm := True
          evalKan := True
          updateTgn := True
          rotatePhase := True
          when(neuromorphicCore.io.done && ssm.io.done && kan.io.done && tgn.io.updated && phaseRot.io.entangled) {
            goto(output)
          }
        }
        onExit {
          trigNeu := False
          stepSsm := False
          evalKan := False
          updateTgn := False
          rotatePhase := False
        }
      }
      val output = new State {
        whenIsActive {
          when(io.output_data.valid && io.output_data.ready) {
            goto(idle)
          }
        }
      }
    }
  }
}

case class NeuromorphicCore() extends Component {
  val io = new Bundle {
    val input = slave Stream Bits(32 bits)
    val output = master Stream Bits(32 bits)
    val trigger = in Bool
    val ready = out Bool
    val done = out Bool
  }

  val busy = Reg(Bool()) init(False)
  val doneReg = Reg(Bool()) init(False)

  io.output.payload := io.input.payload
  io.output.valid := io.input.valid && busy
  io.input.ready := io.output.ready && busy

  when(io.trigger && !busy) {
    busy := True
    doneReg := False
  }

  when(io.output.fire) {
    busy := False
    doneReg := True
  } otherwise {
    when(doneReg) {
      doneReg := False
    }
  }

  io.ready := !busy
  io.done := doneReg
}

case class SSMModule() extends Component {
  val io = new Bundle {
    val step = in Bool
    val state = out Bits(18432 bits)
    val done = out Bool
    val stable = out Bool
  }

  val stateReg = Reg(Bits(18432 bits)) init(0)
  val doneReg = Reg(Bool()) init(False)

  when(io.step) {
    stateReg := (stateReg | B(1, 18432 bits)).rotateLeft(1)
    doneReg := True
  } otherwise {
    when(doneReg) {
      doneReg := False
    }
  }

  io.state := stateReg
  io.done := doneReg
  io.stable := True
}

case class KANLayer(grid: Int) extends Component {
  val io = new Bundle {
    val eval = in Bool
    val basis = out Vec(Bits(16 bits), grid)
    val output = out Vec(Bits(16 bits), 1)
    val done = out Bool
    val converged = out Bool
  }

  val basisReg = Vec(Reg(Bits(16 bits)) init(0), grid)
  val doneReg = Reg(Bool()) init(False)

  when(io.eval) {
    for (g <- 0 until grid) {
      basisReg(g) := U(g, 16 bits).asBits
    }
    doneReg := True
  } otherwise {
    when(doneReg) {
      doneReg := False
    }
  }

  io.basis := basisReg
  io.output(0) := basisReg.reduceBalancedTree(_ +^ _).resized
  io.done := doneReg
  io.converged := True
}

case class TGNUpdateUnit() extends Component {
  val io = new Bundle {
    val update = in Bool
    val updated = out Bool
  }

  val updatedReg = Reg(Bool()) init(False)

  when(io.update) {
    updatedReg := True
  } otherwise {
    when(updatedReg) {
      updatedReg := False
    }
  }

  io.updated := updatedReg
}

case class PhaseRotator(numQubits: Int) extends Component {
  val io = new Bundle {
    val phi = in Bits(64 bits)
    val control = in Bool
    val rotate = in Bool
    val entangled = out Bool
    val phases = out Vec(Bits(64 bits), numQubits)
  }

  val phasesReg = Vec(Reg(Bits(64 bits)) init(0), numQubits)
  val entReg = Reg(Bool()) init(False)

  when(io.rotate && io.control) {
    for (q <- 0 until numQubits) {
      phasesReg(q) := io.phi ^ U(q, 64 bits).asBits
    }
    entReg := True
  } otherwise {
    when(entReg) {
      entReg := False
    }
  }

  io.phases := phasesReg
  io.entangled := entReg
}

